if (!timingSafeEqual(req.query.state, session.state)) throw Error('Invalid OAuth state');
const token = await exchangeCode({
  code: req.query.code,
  redirectUri: process.env.XERO_REDIRECT_URI,
  basicAuth: [process.env.XERO_CLIENT_ID, process.env.XERO_CLIENT_SECRET]
});
await saveEncryptedTokensAtomically(token, customerId);
const connections = await getConnections(token.access_token);
await saveSelectedTenant(customerId, connections[0].tenantId);
